create or replace function public.create_organization_unit(target_organization_id uuid,target_type public.organization_unit_type,target_code text,target_name text)
returns uuid language plpgsql security definer set search_path=public as $$ declare unit_id uuid;
begin if not public.has_organization_role(target_organization_id,array['SUPER_ADMIN','ORG_ADMIN','MANAGER']::public.platform_role[]) then raise exception 'ORGANIZATION_UNIT_NOT_AUTHORIZED'; end if; if coalesce(length(trim(target_code)),0) not between 1 and 100 or coalesce(length(trim(target_name)),0) not between 2 and 240 then raise exception 'ORGANIZATION_UNIT_INVALID_INPUT'; end if;
insert into public.organization_units(organization_id,unit_type,code,name) values(target_organization_id,target_type,trim(target_code),trim(target_name)) returning id into unit_id;
insert into public.audit_logs(organization_id,actor_id,action,entity_type,entity_id,after_value,source) values(target_organization_id,auth.uid(),'ORGANIZATION_UNIT_CREATED','organization_unit',unit_id,jsonb_build_object('type',target_type,'code',trim(target_code)),'WEB'); return unit_id; end; $$;
create or replace function public.assign_collaborator_organization(target_collaborator_id uuid,target_company_unit_id uuid default null,target_department_unit_id uuid default null,target_cost_center_unit_id uuid default null,target_work_site_unit_id uuid default null,target_starts_on date default current_date,target_ends_on date default null)
returns uuid language plpgsql security definer set search_path=public as $$ declare collaborator public.collaborators%rowtype; assignment_id uuid;
begin select * into collaborator from public.collaborators where id=target_collaborator_id for update; if collaborator.id is null or not public.has_organization_role(collaborator.organization_id,array['SUPER_ADMIN','ORG_ADMIN','MANAGER']::public.platform_role[]) then raise exception 'COLLABORATOR_ASSIGNMENT_NOT_AUTHORIZED'; end if; if target_starts_on is null or (target_ends_on is not null and target_ends_on<target_starts_on) then raise exception 'COLLABORATOR_ASSIGNMENT_INVALID_DATES'; end if;
insert into public.collaborator_assignments(organization_id,collaborator_id,company_unit_id,department_unit_id,cost_center_unit_id,work_site_unit_id,starts_on,ends_on,created_by) values(collaborator.organization_id,collaborator.id,target_company_unit_id,target_department_unit_id,target_cost_center_unit_id,target_work_site_unit_id,target_starts_on,target_ends_on,auth.uid()) returning id into assignment_id;
insert into public.audit_logs(organization_id,actor_id,action,entity_type,entity_id,after_value,source) values(collaborator.organization_id,auth.uid(),'COLLABORATOR_ASSIGNED','collaborator_assignment',assignment_id,jsonb_build_object('collaborator_id',collaborator.id,'starts_on',target_starts_on,'ends_on',target_ends_on),'WEB'); return assignment_id; end; $$;
revoke all on function public.create_organization_unit(uuid,public.organization_unit_type,text,text),public.assign_collaborator_organization(uuid,uuid,uuid,uuid,uuid,date,date) from public;
grant execute on function public.create_organization_unit(uuid,public.organization_unit_type,text,text),public.assign_collaborator_organization(uuid,uuid,uuid,uuid,uuid,date,date) to authenticated;
